// DSHA_DIRECTORY_PICKER_INDEPENDENT_LIFETIME_V1
// Browsing depends on the real picker backend, independently of Workspace
// registry hydration. Each child keeps its original dependency and teardown.
const directoryPickerComposition = Symbol("dsha.directoryPicker.composed");
const WorkspaceControllerPlugin = {
	name: WorkspaceController.name,
	Config: WorkspaceController.Config,
	apply(ctx, config) {
		ctx.plugin(DirectoryPickerController);
		ctx.extend({ [directoryPickerComposition]: true }).plugin(WorkspaceController, config);
	}
};
export { DirectoryPickerController, WorkspaceController, WorkspaceControllerPlugin as default };
